from __future__ import annotations

import base64
import gzip
import hashlib
from pathlib import Path
import shutil

REPO_ROOT = Path(__file__).resolve().parents[1]
TARGET = REPO_ROOT / "notebooks" / "28_bha_historical_race_data_depth.ipynb"
BACKUP = (
    REPO_ROOT
    / "data"
    / "cache"
    / "bha_historical_race_data_depth"
    / "notebook_28_pre_autonomous_backup.ipynb"
)
EXPECTED_SHA256 = "01921b6c94a6199fbbacae7703cd34f5a0ca6d8be718efce5475f7b86ec71afd"

# The notebook is embedded as gzip+base64 so this builder can safely replace the
# local, currently-uncommitted Notebook 28 without requiring the notebook itself
# to exist on the remote branch first. The previous local notebook is backed up
# into the ignored data/cache tree before replacement.
PAYLOAD = """"""

notebook_bytes = gzip.decompress(base64.b64decode(PAYLOAD))
actual_sha256 = hashlib.sha256(notebook_bytes).hexdigest()
if actual_sha256 != EXPECTED_SHA256:
    raise RuntimeError(
        f"Embedded Notebook 28 checksum mismatch: {actual_sha256} != {EXPECTED_SHA256}"
    )

TARGET.parent.mkdir(parents=True, exist_ok=True)
BACKUP.parent.mkdir(parents=True, exist_ok=True)

if TARGET.exists() and not BACKUP.exists():
    shutil.copy2(TARGET, BACKUP)
    print(f"Backed up existing Notebook 28 to: {BACKUP}")

TARGET.write_bytes(notebook_bytes)
print(f"Wrote autonomous Notebook 28: {TARGET}")
print(f"sha256: {actual_sha256}")
